package cli

import (
	_ "embed"
	"encoding/json"
	"strings"
)

// commanddefs.json is generated by oracle/scripts/command-dump.php from the
// pinned Composer checkout (see its _notice field for source and license).
// It is the single source for command names, aliases, descriptions, option
// and argument definitions, help texts and synopses, so that list/help output
// and error synopses match Composer exactly.
//
//go:embed commanddefs.json
var commandDefsJSON []byte

type rawOpt struct {
	Name          string      `json:"name"`
	Shortcut      *string     `json:"shortcut"`
	AcceptValue   bool        `json:"accept_value"`
	ValueRequired bool        `json:"value_required"`
	ValueOptional bool        `json:"value_optional"`
	Array         bool        `json:"array"`
	Negatable     bool        `json:"negatable"`
	Description   string      `json:"description"`
	Default       interface{} `json:"default"`
}

type rawArg struct {
	Name        string      `json:"name"`
	Required    bool        `json:"required"`
	Array       bool        `json:"array"`
	Description string      `json:"description"`
	Default     interface{} `json:"default"`
}

type rawCommand struct {
	Name        string   `json:"name"`
	Aliases     []string `json:"aliases"`
	Hidden      bool     `json:"hidden"`
	Description string   `json:"description"`
	Help        string   `json:"help"`
	Usages      []string `json:"usages"`
	Arguments   []rawArg `json:"arguments"`
	Options     []rawOpt `json:"options"`
	Synopsis    string   `json:"synopsis"`
}

type rawDefs struct {
	Commands      []rawCommand `json:"commands"`
	GlobalOptions []rawOpt     `json:"global_options"`
}

var commandDefs = func() rawDefs {
	var d rawDefs
	if err := json.Unmarshal(commandDefsJSON, &d); err != nil {
		panic("commanddefs.json: " + err.Error())
	}
	return d
}()

func convertOpt(o rawOpt) OptDef {
	d := OptDef{Name: o.Name, Desc: o.Description, Negatable: o.Negatable, RawDefault: o.Default}
	if o.Shortcut != nil {
		d.Shortcut = *o.Shortcut
	}
	switch {
	case o.Array:
		d.Kind = OptArray
	case o.ValueRequired:
		d.Kind = OptRequired
	case o.ValueOptional:
		d.Kind = OptOptional
	}
	if s, ok := o.Default.(string); ok {
		d.Default = s
	}
	return d
}

func defOptions(raw []rawOpt) []OptDef {
	out := make([]OptDef, 0, len(raw))
	for _, o := range raw {
		out = append(out, convertOpt(o))
	}
	return out
}

// applyDefs copies Composer's definition of cmd.Name onto cmd.
func applyDefs(cmd *Command, def rawCommand) {
	cmd.Name = def.Name
	cmd.Aliases = def.Aliases
	cmd.Hidden = def.Hidden
	cmd.Description = def.Description
	cmd.Help = def.Help
	cmd.Usages = def.Usages
	cmd.Synopsis = def.Synopsis
	cmd.Options = defOptions(def.Options)
	cmd.Args = nil
	for _, a := range def.Arguments {
		cmd.Args = append(cmd.Args, ArgDef{Name: a.Name, Required: a.Required, Array: a.Array, Desc: a.Description, RawDefault: a.Default})
	}
}

// synopsisFor is InputDefinition::getSynopsis for commands without a
// recorded synopsis.
func synopsisFor(cmd *Command) string {
	if cmd.Synopsis != "" {
		return cmd.Synopsis
	}
	var el []string
	for _, o := range cmd.Options {
		value := ""
		switch o.Kind {
		case OptRequired, OptArray:
			value = " " + strings.ToUpper(o.Name)
		case OptOptional:
			value = " [" + strings.ToUpper(o.Name) + "]"
		}
		short := ""
		if o.Shortcut != "" {
			short = "-" + o.Shortcut + "|"
		}
		neg := ""
		if o.Negatable {
			neg = "|--no-" + o.Name
		}
		el = append(el, "["+short+"--"+o.Name+value+neg+"]")
	}
	if len(el) > 0 && len(cmd.Args) > 0 {
		el = append(el, "[--]")
	}
	tail := ""
	for _, a := range cmd.Args {
		e := "<" + a.Name + ">"
		if a.Array {
			e += "..."
		}
		if !a.Required {
			e = "[" + e
			tail += "]"
		}
		el = append(el, e)
	}
	return strings.TrimSpace(cmd.Name + " " + strings.Join(el, " ") + tail)
}
